import {debounce} from "/Users/chris/Code/Verification/zig-js-ecosystem-2026-11-08/stx-immutable-cohort/candidate/storage/framework/core/browser/src/utils/debounce.ts";
function check(value: boolean, label: string) { if(!value)throw new Error(label); }
let cases=0;
let calls=0;
const trailing=debounce((value:number)=>{calls++;return value*2},20);
const first=trailing(2),second=trailing(3);
const flushed=await trailing.flush();
check(flushed===6&&(await first)===6&&(await second)===6&&calls===1,"coalesced trailing flush");cases++;
let cancelledCalls=0;
const cancelled=debounce(()=>{cancelledCalls++;return 1},20);
const cancelledValue=cancelled();cancelled.cancel();
check((await cancelledValue)===undefined&&cancelledCalls===0,"cancel resolves without invocation");cases++;
const timed=debounce((value:number)=>value*2,2);
check((await timed(4))===8,"actual timer callback");cases++;
const receiver=debounce(function(this:{base:number},value:number){return this.base+value},20);
const receiverValue=receiver.call({base:5},2);
check((await receiver.flush())===7&&(await receiverValue)===7,"receiver and arguments");cases++;
const asynchronous=debounce(async(value:number)=>value*3,20);
const asynchronousValue=asynchronous(2);
check((await asynchronous.flush())===6&&(await asynchronousValue)===6,"async return adoption");cases++;
const failure=new Error("actual debounce failure");
const rejected=debounce(async()=>{throw failure},20);
const pending=rejected();
const observed=pending.then(()=>{throw new Error("rejection resolved")},error=>error);
let caught;try{await rejected.flush()}catch(error){caught=error}
check(caught===failure&&(await observed)===failure,"rejection identity");cases++;
let leadingCalls=0;
const leading=debounce((value:number)=>{leadingCalls++;return value},20,{leading:true,trailing:false});
check((await leading(9))===9&&leadingCalls===1,"leading result");leading.cancel();cases++;
check(cases===7,"incomplete consumer probes");console.log("OK 7 actual Stacks debounce behaviors");

